@page "/settings"
@rendermode InteractiveServer
@using sv_56742560570446149a39fd5dcf71b42b.Services
@using sv_56742560570446149a39fd5dcf71b42b.Components.Pages.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h3 class="mb-4">Settings</h3>
    <div class="row">
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetSection" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Security="@_security"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevokeSession="RevokeSessionAsync" />
